theme.template:
QMainWindow, QWidget {
    background-color: {surface};
    color: {on_surface};
    font-family: "Segoe UI", "Roboto", sans-serif;
    font-size: 14px;
}

QLabel { color: {on_surface}; }
QTextBrowser { background-color: transparent; border: none; }

QLineEdit, QTextEdit {
    background-color: {surface_container_lowest};
    color: {on_surface};
    border: 1px solid {outline};
    border-radius: {radius_extra_small}px;
    padding: 10px;
    selection-background-color: {primary};
    selection-color: {on_primary};
}
QLineEdit:focus, QTextEdit:focus {
    border: 2px solid {primary};
    padding: 9px;
}

QComboBox {
    background-color: {surface_container_lowest};
    color: {on_surface};
    border: 1px solid {outline};
    border-radius: {radius_extra_small}px;
    padding: 8px 10px;
}
QComboBox::drop-down { border: none; width: 24px; }
QComboBox::down-arrow {
    image: none;
    width: 0px; height: 0px;
    border-left: 5px solid transparent;
    border-right: 5px solid transparent;
    border-top: 5px solid {on_surface};
    margin-right: 8px;
}
QComboBox:focus { border: 1px solid {primary}; }

QComboBoxPrivateContainer { background: transparent; border: none; }
QComboBox QAbstractItemView { background: transparent; border: none; outline: 0; }

QScrollBar:vertical {
    border: none; background: transparent; width: 8px; margin: 0px;
}
QScrollBar::handle:vertical {
    background: {outline_variant};
    min-height: 30px; border-radius: 4px;
}
QScrollBar::handle:vertical:hover { background: {outline}; }
QScrollBar::add-line:vertical, QScrollBar::sub-line:vertical { height: 0px; }
QScrollBar::add-page:vertical, QScrollBar::sub-page:vertical { background: none; }

QScrollBar:horizontal {
    border: none; background: transparent; height: 8px; margin: 0px;
}
QScrollBar::handle:horizontal {
    background: {outline_variant};
    min-width: 30px; border-radius: 4px;
}
QScrollBar::handle:horizontal:hover { background: {outline}; }
QScrollBar::add-line:horizontal, QScrollBar::sub-line:horizontal { width: 0px; }
QScrollBar::add-page:horizontal, QScrollBar::sub-page:horizontal { background: none; }

QCheckBox, QRadioButton {
    color: {on_surface};
    spacing: 8px; background: transparent; outline: none;
}
QCheckBox::indicator, QRadioButton::indicator { width: 0px; height: 0px; }

QToolTip {
    background-color: {surface_container_high};
    color: {on_surface};
    border: 1px solid {outline_variant};
    border-radius: {radius_extra_small}px;
    padding: 4px;
}
